import { useRangePair } from './useRangePair';
import { panelStyle } from './styles';

export type Range = { start: number; end: number };
export type Props = { min: number; max: number; onApply: (range: Range) => void };

export function Component({ min, max, onApply }: Props) {
  const { start, end, setStart, setEnd, errors, submit } = useRangePair(onApply);
  const options = Array.from({ length: max - min + 1 }, (_, index) => min + index);

  return (
    <form aria-label="Range pair" data-testid="panel" style={panelStyle} onSubmit={submit}>
      <label>
        Start
        <select value={start} onChange={event => setStart(event.currentTarget.value)} aria-invalid={errors.start || undefined}>
          <option value="">Choose</option>
          {options.map(value => <option key={value} value={String(value)}>{value}</option>)}
        </select>
      </label>
      <label>
        End
        <select value={end} onChange={event => setEnd(event.currentTarget.value)} aria-invalid={errors.end || undefined}>
          <option value="">Choose</option>
          {options.map(value => <option key={value} value={String(value)}>{value}</option>)}
        </select>
      </label>
      {errors.message && <p role="alert">{errors.message}</p>}
      <button type="submit">Apply</button>
    </form>
  );
}

