import { useState, type FormEvent } from 'react';
import type { Props } from './Component';

export function useRangePair(onApply: Props['onApply']) {
  const [start, setStart] = useState('');
  const [end, setEnd] = useState('');
  const [errors, setErrors] = useState({ message: '', start: false, end: false });

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (start === '' || end === '') {
      setErrors({ message: 'Choose both values', start: start === '', end: end === '' });
      return;
    }
    const range = { start: Number(start), end: Number(end) };
    if (range.start > range.end) {
      setErrors({ message: 'Range order', start: false, end: true });
      return;
    }
    setErrors({ message: '', start: false, end: false });
    onApply(range);
  }

  return { start, end, setStart, setEnd, errors, submit };
}

